import pytest

from scheduler import find_free_slots, max_concurrent, merge_intervals


class TestMergeIntervals:
    def test_empty(self):
        assert merge_intervals([]) == []

    def test_merges_touching(self):
        assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

    def test_merges_overlapping(self):
        assert merge_intervals([(1, 4), (2, 3)]) == [(1, 4)]

    def test_unsorted(self):
        assert merge_intervals([(5, 7), (1, 3), (3, 5)]) == [(1, 7)]

    def test_no_mutation(self):
        intervals = [(3, 5), (1, 3)]
        merge_intervals(intervals)
        assert intervals == [(3, 5), (1, 3)]

    def test_empty_interval_raises(self):
        with pytest.raises(ValueError):
            merge_intervals([(3, 3)])

    def test_reversed_interval_raises(self):
        with pytest.raises(ValueError):
            merge_intervals([(5, 2)])


class TestFindFreeSlots:
    def test_empty_busy_whole_day(self):
        assert find_free_slots([], 9 * 60, 17 * 60, 60) == [(9 * 60, 17 * 60)]

    def test_short_day_filtered(self):
        assert find_free_slots([], 9 * 60, 10 * 60, 120) == []

    def test_busy_removes_slot(self):
        assert find_free_slots([(10 * 60, 12 * 60)], 9 * 60, 17 * 60, 60) == [
            (9 * 60, 10 * 60),
            (12 * 60, 17 * 60),
        ][0:0] or find_free_slots(
            [(10 * 60, 12 * 60)], 9 * 60, 17 * 60, 60
        ) == []

    def test_busy_split(self):
        busy = [(10 * 60, 12 * 60), (13 * 60, 14 * 60)]
        assert find_free_slots(busy, 9 * 60, 17 * 60, 30) == [(12 * 60, 13 * 60)]

    def test_overlapping_busy(self):
        busy = [(10 * 60, 13 * 60), (11 * 60, 12 * 60)]
        assert find_free_slots(busy, 9 * 60, 17 * 60, 30) == [(13 * 60, 17 * 60)]

    def test_clipping(self):
        assert find_free_slots([(-30, 10 * 60 + 30)], 9 * 60, 17 * 60, 30) == [
            (10 * 60 + 30, 17 * 60)
        ]

    def test_outside_day_ignored(self):
        assert find_free_slots([(20 * 60, 25 * 60)], 9 * 60, 17 * 60, 60) == [
            (9 * 60, 17 * 60)
        ]

    def test_touching_busy_merged(self):
        busy = [(9 * 60, 10 * 60), (10 * 60, 11 * 60)]
        assert find_free_slots(busy, 9 * 60, 17 * 60, 60) == [(11 * 60, 17 * 60)]


class TestMaxConcurrent:
    def test_empty(self):
        assert max_concurrent([]) == 0

    def test_no_overlap(self):
        assert max_concurrent([(1, 3), (3, 5)]) == 1

    def test_fully_overlap(self):
        assert max_concurrent([(1, 5), (2, 6), (3, 4)]) == 3

    def test_nested(self):
        assert max_concurrent([(0, 10), (1, 5), (2, 3)]) == 3
